-- Original competitive-exam-style Fluid Mechanics MCQs for the JobForSure bank.
-- Topic coverage is informed by common IES/ESE, ISRO, AE, and AEE syllabi.
-- Questions are original and are not copied from past papers.
-- Run after practice_question_functions.sql.

DO $seed$
DECLARE
    v_branch_id UUID;
    v_subject_id UUID;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.engineering_branches
        WHERE name = 'Civil Engineering'
    ) THEN
        INSERT INTO public.engineering_branches (name, code, description, is_active)
        VALUES (
            'Civil Engineering',
            CASE WHEN EXISTS (
                SELECT 1 FROM public.engineering_branches WHERE code = 'CE'
            ) THEN 'CE-' || upper(substr(replace(gen_random_uuid()::TEXT, '-', ''), 1, 8))
            ELSE 'CE' END,
            'Civil engineering branch', TRUE
        );
    END IF;

    SELECT id INTO v_branch_id
    FROM public.engineering_branches
    WHERE name = 'Civil Engineering';

    IF v_branch_id IS NULL THEN
        RAISE EXCEPTION 'Could not create or find the Civil Engineering branch';
    END IF;

    INSERT INTO public.subjects (
        branch_id, name, code, description, display_order, is_active
    ) VALUES (
        v_branch_id, 'Fluid Mechanics', 'FM',
        'Fluid properties, hydrostatics, flow, pipes, channels, pumps, and turbines', 0, TRUE
    ) ON CONFLICT (branch_id, name) DO NOTHING;

    SELECT s.id INTO v_subject_id
    FROM public.subjects s
    WHERE s.branch_id = v_branch_id AND s.name = 'Fluid Mechanics';

    IF v_subject_id IS NULL THEN
        RAISE EXCEPTION 'Could not create or find Fluid Mechanics under Civil Engineering';
    END IF;

    INSERT INTO public.practice_questions (
        subject_id, topic_id, question_text, question_type, options,
        correct_answer, explanation, difficulty, points, display_order,
        is_published
    )
    SELECT
        v_subject_id,
        topic.id,
        seed.question_text,
        'mcq',
        jsonb_build_array(
            jsonb_build_object('value', 'A', 'text', seed.option_a),
            jsonb_build_object('value', 'B', 'text', seed.option_b),
            jsonb_build_object('value', 'C', 'text', seed.option_c),
            jsonb_build_object('value', 'D', 'text', seed.option_d)
        ),
        seed.correct_answer,
        seed.explanation,
        seed.difficulty,
        10,
        seed.display_order,
        TRUE
    FROM (
        VALUES
        -- Fluid properties (1-20)
