        ('Fluid Properties', 'Kinematic viscosity is equal to:', 'Dynamic viscosity divided by density', 'Density divided by dynamic viscosity', 'Dynamic viscosity multiplied by gravity', 'Pressure divided by density', 'A', 'Kinematic viscosity nu = mu/rho.', 'easy', 4),
        ('Fluid Properties', 'The SI unit of dynamic viscosity is:', 'm2/s', 'Pa s', 'N/m', 'kg/m2', 'B', 'Dynamic viscosity has SI units Pa s, equivalent to kg/(m s).', 'easy', 5),
