        ('Fluid Properties', 'Bulk modulus measures a fluid resistance to:', 'Shear deformation', 'Volumetric compression', 'Thermal expansion', 'Surface tension', 'B', 'Bulk modulus is the pressure change divided by relative volume change.', 'medium', 9),
        ('Fluid Properties', 'Cavitation can begin when local absolute pressure falls below the fluid:', 'Atmospheric pressure', 'Vapor pressure', 'Critical pressure only', 'Gauge pressure', 'B', 'Vapor cavities form when local absolute pressure reaches the vapor pressure.', 'easy', 10),
        ('Fluid Properties', 'Absolute pressure is related to gauge pressure by:', 'p_abs = p_gauge + p_atm', 'p_abs = p_atm - p_gauge always', 'p_abs = p_gauge/rho', 'p_abs = rho g p_gauge', 'A', 'Gauge pressure is measured relative to atmospheric pressure.', 'easy', 11),
